/**
 * Unit tests for JacksonAnnotationIntrospector#findEnumValues
 */
public class JacksonAnnotationIntrospector_findEnumValues_TriageGen0Test {

    private JacksonAnnotationIntrospector introspector;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    // Test Case 1: Enum with @JsonProperty annotations
    enum TestEnumWithAnnotation {
        @JsonProperty("val_one")
        ONE,
        @JsonProperty("val_two")
        TWO,
        THREE // No annotation
    }

    @Test
    public void testFindEnumValues_WithAnnotations() {
        Class<?> enumType = TestEnumWithAnnotation.class;
        TestEnumWithAnnotation[] enumValues = TestEnumWithAnnotation.values();
        // Initial names are usually the enum names themselves or nulls
        String[] names = new String[enumValues.length];
        for (int i = 0; i < names.length; i++) {
            names[i] = enumValues[i].name();
        }

        String[] result = introspector.findEnumValues(enumType, enumValues, names);

        String[] expected = {"val_one", "val_two", "THREE"};
        assertArrayEquals(expected, result);
    }

    // Test Case 2: Enum with empty @JsonProperty value (should be skipped)
    enum TestEnumEmptyAnnotation {
        @JsonProperty("")
        EMPTY,
        @JsonProperty("valid")
        VALID
    }

    @Test
    public void testFindEnumValues_WithEmptyAnnotationValue() {
        Class<?> enumType = TestEnumEmptyAnnotation.class;
        TestEnumEmptyAnnotation[] enumValues = TestEnumEmptyAnnotation.values();
        String[] names = new String[enumValues.length];
        for (int i = 0; i < names.length; i++) {
            names[i] = enumValues[i].name();
        }

        String[] result = introspector.findEnumValues(enumType, enumValues, names);

        // EMPTY should remain "EMPTY" because the logic skips empty strings
        String[] expected = {"EMPTY", "valid"};
        assertArrayEquals(expected, result);
    }

    // Test Case 3: Enum with no @JsonProperty annotations at all
    enum TestEnumNoAnnotation {
        A, B, C
    }

    @Test
    public void testFindEnumValues_NoAnnotations() {
        Class<?> enumType = TestEnumNoAnnotation.class;
        TestEnumNoAnnotation[] enumValues = TestEnumNoAnnotation.values();
        String[] names = new String[enumValues.length];
        for (int i = 0; i < names.length; i++) {
            names[i] = enumValues[i].name();
        }

        String[] result = introspector.findEnumValues(enumType, enumValues, names);

        // Result should be identical to input names because expl is null
        String[] expected = {"A", "B", "C"};
        assertArrayEquals(expected, result);
    }

    // Test Case 4: Enum with non-enum constant fields (should be ignored)
    enum TestEnumWithFields {
        @JsonProperty("val")
        VALID,
        A
    }
    // Note: In Java, enum constants are fields. To test the !f.isEnumConstant() branch, 
    // we would need a class that looks like an enum but has other fields, 
    // but the method signature expects Enum<?>[]. 
    // However, the logic specifically checks f.isEnumConstant().

    @Test
    public void testFindEnumValues_MixedFields() {
        // Since we can't easily add non-enum fields to an Enum class via standard syntax,
        // we rely on the fact that the method iterates through all declared fields.
        // The logic handles the branch via the isEnumConstant() check.
        Class<?> enumType = TestEnumWithAnnotation.class;
        TestEnumWithAnnotation[] enumValues = TestEnumWithAnnotation.values();
        String[] names = new String[enumValues.length];
        // If we pass a class that isn't an enum, the behavior is undefined by signature, 
        // but the code uses ClassUtil.getDeclaredFields.

        String[] result = introspector.findEnumValues(enumType, enumValues, names);
        // This ensures the loop completes without exception.
        assertEquals(enumValues.length, result.length);
    }

    // Test Case 5: Test with null names array or empty enum array (Edge cases)
    @Test
    public void testFindEnumValues_EmptyEnumArray() {
        Class<?> enumType = TestEnumWithAnnotation.class;
        TestEnumWithAnnotation[] enumValues = new TestEnumWithAnnotation[0];
        String[] names = new String[0];

        String[] result = introspector.findEnumValues(enumType, enumValues, names);
        assertEquals(0, result.length);
    }

    // Test Case 6: Verify that names array is modified in place (as per implementation)
    @Test
    public void testFindEnumValues_InPlaceModification() {
        Class<?> enumType = TestEnumWithAnnotation.class;
        TestEnumWithAnnotation[] enumValues = TestEnumWithAnnotation.values();
        String[] names = {"ONE", "TWO", "THREE"};

        introspector.findEnumValues(enumType, enumValues, names);

        assertEquals("val_one", names[0]);
        assertEquals("val_two", names[1]);
        assertEquals("THREE", names[2]);
    }
}
